mapper.select:
select material_batch_num as materialBatchNum,
material_name as materialName,
maintain_stage as maintainStage,
site_name as siteName,
apply_time as applyTime
from tb_maintain_plan

    1=1

        and material_batch_num = #{maintainPlanDto.materialBatchNum}


        and material_name = #{maintainPlanDto.tobaccoName}


        and site_name = #{maintainPlanDto.siteName}


        and apply_time = #{maintainPlanDto.dateOfApplyFor}


order by create_time desc
